function getSelectValue(clientId) {
    if (!clientId) {
        return "";
    }
    var el = document.getElementById(clientId);
    if (!el) {
        return "";
    }
    // Select2 / native select multiple
    if (el.tagName === "SELECT" && el.multiple) {
        var selectedValues = [];
        var i;
        for (i = 0; i < el.options.length; i++) {
            if (el.options[i].selected) {
                selectedValues.push(el.options[i].value);
            }
        }
        if (selectedValues.length === 0) {
            return "";
        }
        if (selectedValues.length === el.options.length) {
            return "";
        }
        return selectedValues.join(",");
    }
    if (el.classList && el.classList.contains("scs-ms-wrap")) {
        var allCheck = el.querySelector(".scs-ms-check-all");
        if (allCheck && allCheck.checked) {
            return "";
        }
        var checks = el.querySelectorAll(".scs-ms-check:checked");
        var values = [];
        for (i = 0; i < checks.length; i++) {
            values.push(checks[i].value);
        }
        return values.join(",");
    }
    return el.value;
}

