/* ===== Select2 cho filter Lớp ===== */
function initSelect2Class() {
    var select = document.getElementById("scsSelectClass");
    if (!select) return;
    if (typeof jQuery === "undefined" || !jQuery.fn.select2) return;

    jQuery(select).select2({
        placeholder: "Tất cả lớp — gõ để tìm nhanh",
        dropdownCssClass: "scs-select2-drop",
        width: "100%",
        closeOnSelect: false,
        allowClear: false
    });

    jQuery(select).on("change", function () {
        onClassFilterChange();
    });
}

function fillSelect2Class(rows, preserveValue) {
    var select = document.getElementById("scsSelectClass");
    if (!select) return;

    var savedValues = [];
    if (preserveValue && String(preserveValue).trim() !== "") {
        savedValues = String(preserveValue).split(",");
    }

    // Xóa options cũ
    select.innerHTML = "";

    var i, row, option;
    for (i = 0; i < rows.length; i++) {
        row = rows[i];
        option = document.createElement("option");
        option.value = row["ClassID"] !== null && row["ClassID"] !== undefined ? String(row["ClassID"]) : "";
        option.text = row["ClassName"] !== null && row["ClassName"] !== undefined ? String(row["ClassName"]) : "";
        select.appendChild(option);
    }

    if (typeof jQuery !== "undefined" && jQuery.fn.select2) {
        var jqSelect = jQuery(select);
        // Destroy và re-init để cập nhật options
        if (jqSelect.hasClass("select2-hidden-accessible")) {
            jqSelect.select2("destroy");
        }
        jqSelect.select2({
            placeholder: "Tất cả lớp — gõ để tìm nhanh",
            dropdownCssClass: "scs-select2-drop",
            width: "100%",
            closeOnSelect: false,
            allowClear: false
        });

        jqSelect.off("change").on("change", function () {
            onClassFilterChange();
        });

        // Khôi phục giá trị đã chọn trước đó
        if (savedValues.length > 0) {
            jqSelect.val(savedValues).trigger("change");
        }
    }
}

